def find_path(graph, start, goal):
    """
    Implement a path search algorithm to find a path from start to goal in a graph.
    graph: A dict mapping each node to a list of neighbouring nodes (directed edges).
    start: The start node.
    goal: The goal node.
    Return: A list of nodes from start to goal that follows existing edges, or None if goal is unreachable.
    """
    if start == goal:
        return [start]

    def depth_first_search(graph, start, goal, path):
        path = path + [start]
        if start == goal:
            return path
        if start not in graph:
            return None
        for node in graph[start]:
            if node not in path:
                new_path = depth_first_search(graph, node, goal, path)
                if new_path: 
                    return new_path
        return None

    result = depth_first_search(graph, start, goal, [])
    return result
